#ifndef EPIC_CLEAN_H
#define EPIC_CLEAN_H

#include <stdbool.h>
#include <stddef.h>
#include <stdint.h>
#include <netinet/in.h>

#define EPIC_STAR4_HOSTS 4
#define EPIC_ROCE_UDP_PORT 4791
#define EPIC_DEFAULT_PAYLOAD_BYTES 1024
#define EPIC_MAX_PAYLOAD_BYTES 4096
#define EPIC_DEFAULT_COUNT 4096
#define EPIC_DEFAULT_ITERS 1
#define EPIC_DEFAULT_GID_INDEX 1
#define EPIC_DEFAULT_IB_PORT 1
#define EPIC_DEFAULT_SEGMENT_WINDOW 16
#define EPIC_DEFAULT_RECV_WINDOW 1024
#define EPIC_DEFAULT_QP_TIMEOUT 0x12
#define EPIC_FAKE_SWITCH_QPN_BASE 0x00ee0000u
#define EPIC_PSN_WINDOW 65536

typedef enum {
    EPIC_PRIM_ALLREDUCE = 0,
    EPIC_PRIM_REDUCE = 1,
    EPIC_PRIM_BCAST = 2,
    EPIC_PRIM_BARRIER = 3,
    EPIC_PRIM_ALLGATHER = 4,
    EPIC_PRIM_REDUCESCATTER = 5,
} epic_primitive_t;

typedef enum {
    EPIC_MODE_NON_TERMINATION = 2,
    EPIC_MODE_TERMINATION = 3,
} epic_mode_t;

typedef struct __attribute__((packed)) {
    uint8_t dst_mac[6];
    uint8_t src_mac[6];
    uint16_t ether_type;
} epic_eth_t;

typedef struct __attribute__((packed)) {
    uint8_t version_ihl;
    uint8_t tos;
    uint16_t total_length;
    uint16_t id;
    uint16_t flags_frag_off;
    uint8_t ttl;
    uint8_t protocol;
    uint16_t checksum;
    uint32_t src_ip;
    uint32_t dst_ip;
} epic_ipv4_t;

typedef struct __attribute__((packed)) {
    uint16_t src_port;
    uint16_t dst_port;
    uint16_t length;
    uint16_t checksum;
} epic_udp_t;

typedef struct __attribute__((packed)) {
    uint8_t opcode;
    uint8_t se_m_pad;
    uint16_t pkey;
    uint32_t qpn;
    uint32_t apsn;
} epic_bth_t;

typedef struct __attribute__((packed)) {
    uint32_t syn_msn;
} epic_aeth_t;

typedef struct {
    bool valid;
    bool is_data;
    bool is_ack;
    uint8_t opcode;
    uint32_t dst_qpn;
    uint32_t psn;
    uint32_t msn;
    uint32_t src_ip;
    uint32_t dst_ip;
    uint16_t src_port;
    uint16_t dst_port;
    const uint8_t *payload;
    size_t payload_len;
} epic_roce_packet_t;

typedef struct {
    int rank;
    char dev[16];
    uint8_t host_mac[6];
    uint8_t switch_mac[6];
    uint32_t host_ip;
    uint32_t switch_ip;
    uint32_t host_qpn;
    uint32_t switch_qpn;
} epic_port_t;

typedef struct {
    epic_primitive_t primitive;
    epic_mode_t mode;
    int root_rank;
    int count;
    int payload_bytes;
    epic_port_t ports[EPIC_STAR4_HOSTS];
} epic_switch_config_t;

const char *epic_primitive_name(epic_primitive_t primitive);
bool epic_parse_primitive(const char *text, epic_primitive_t *primitive);
bool epic_parse_mode(const char *text, epic_mode_t *mode);
bool epic_parse_ipv4(const char *text, uint32_t *addr);
bool epic_parse_mac(const char *text, uint8_t mac[6]);
const char *epic_ipv4_to_str(uint32_t addr, char *buf, size_t len);
void epic_mac_to_str(const uint8_t mac[6], char *buf, size_t len);

void epic_crc32_init(void);
uint16_t epic_ipv4_checksum(const void *data, size_t len);
uint32_t epic_compute_icrc(const uint8_t *frame, size_t frame_len);

bool epic_parse_roce(const uint8_t *frame, size_t frame_len, epic_roce_packet_t *out);

size_t epic_build_roce_data(uint8_t *frame, size_t frame_cap,
                            const uint8_t src_mac[6], const uint8_t dst_mac[6],
                            uint32_t src_ip, uint32_t dst_ip,
                            uint16_t src_port, uint16_t dst_port,
                            uint32_t dst_qpn, uint32_t psn,
                            const int32_t *payload_host_order,
                            size_t payload_bytes);

size_t epic_build_roce_data_raw(uint8_t *frame, size_t frame_cap,
                                const uint8_t src_mac[6], const uint8_t dst_mac[6],
                                uint32_t src_ip, uint32_t dst_ip,
                                uint16_t src_port, uint16_t dst_port,
                                uint32_t dst_qpn, uint32_t psn,
                                const uint8_t *payload,
                                size_t payload_bytes);

size_t epic_build_roce_ack(uint8_t *frame, size_t frame_cap,
                           const uint8_t src_mac[6], const uint8_t dst_mac[6],
                           uint32_t src_ip, uint32_t dst_ip,
                           uint16_t src_port, uint16_t dst_port,
                           uint32_t dst_qpn, uint32_t psn);

#endif
#ifndef OFFLINE_API_H
#define OFFLINE_API_H
#include <stdint.h>
#include <stddef.h>
typedef int (*epic_emit_fn)(void *user,int rank,const uint8_t *frame,size_t length);
void *epic_open(int primitive,int mode,int root,uint32_t count,uint32_t words,uint32_t capacity,uint32_t start,epic_emit_fn emit,void *user);
void epic_close(void *context);
int epic_ingress(void *context,int rank,const uint8_t *frame,size_t length);
int epic_flush(void *context);
int epic_retry(void *context,int rank);
void epic_state(void *context,uint64_t *state);
uint64_t epic_digest(void *context);
#endif
#ifndef OFFLINE_PORT_H
#define OFFLINE_PORT_H
#include "offline_api.h"
typedef struct { void *user; int rank; epic_emit_fn emit; } pcap_t;
#endif
#include "star4_switch.c"

void *epic_open(int primitive,int mode,int root,uint32_t count,uint32_t words,
                uint32_t capacity,uint32_t start,epic_emit_fn emit,void *user) {
    switch_ctx_t *ctx=calloc(1,sizeof(*ctx));
    if(!ctx)return NULL;
    ctx->capacity=capacity;ctx->input_count=count;ctx->base24=start;
    ctx->slots=calloc(capacity,sizeof(slot_state_t));
    if(!ctx->slots){free(ctx);return NULL;}
    ctx->cfg.primitive=(epic_primitive_t)primitive;ctx->cfg.mode=(epic_mode_t)mode;
    ctx->cfg.root_rank=root;ctx->cfg.payload_bytes=(int)words*4;
    ctx->cfg.count=(int)(count*words*(primitive==EPIC_PRIM_ALLGATHER?4:1));
    for(int r=0;r<4;r++) {
        epic_port_t *p=&ctx->cfg.ports[r];p->rank=r;
        p->host_mac[0]=2;p->host_mac[5]=(uint8_t)(r+1);
        p->switch_mac[0]=2;p->switch_mac[1]=1;p->switch_mac[5]=(uint8_t)(r+1);
        p->host_ip=htonl(0x0a000001u+(uint32_t)r);
        p->switch_ip=htonl(0x0a000065u+(uint32_t)r);
        p->host_qpn=0x100u+(uint32_t)r;p->switch_qpn=0x200u+(uint32_t)r;
        ctx->handles[r]=calloc(1,sizeof(pcap_t));
        if(!ctx->handles[r])abort();
        *ctx->handles[r]=(pcap_t){.user=user,.rank=r,.emit=emit};
    }
    return ctx;
}
void epic_close(void *context) {
    switch_ctx_t *ctx=context;if(!ctx)return;
    for(uint32_t i=0;i<ctx->capacity;i++)cleanup_slot(&ctx->slots[i]);
    for(int r=0;r<4;r++)free(ctx->handles[r]);
    free(ctx->slots);free(ctx);
}
int epic_ingress(void *context,int rank,const uint8_t *frame,size_t length) {
    return handle_packet(context,rank,frame,length);
}
int epic_flush(void *context) {return drain_ordered_results(context);}
int epic_retry(void *context,int rank) {(void)rank;return epic_flush(context);}
void epic_state(void *context,uint64_t *state) {
    switch_ctx_t *ctx=context;memset(state,0,32*sizeof(*state));state[0]=ctx->retired;
    for(uint32_t i=0;i<ctx->capacity;i++)state[1]+=ctx->slots[i].in_use;
    for(int r=0;r<4;r++) {state[2+r]=ctx->rx_next[r];state[6+r]=ctx->sent_next[r];state[10+r]=ctx->ack_next[r];state[14+r]=ctx->up_sent[r];}
    uint64_t values[]={ctx->rx_data,ctx->rx_ack,ctx->tx_data,ctx->tx_ack,ctx->accepted,
      ctx->duplicates,ctx->blocked,ctx->stale,ctx->invalid_wire,ctx->invalid_endpoint,
      ctx->ack_ignored,ctx->failed_sends,ctx->slot_overwrites};
    memcpy(state+18,values,sizeof(values));
}
static uint64_t fold_byte(uint64_t hash,uint8_t value){return (hash^value)*UINT64_C(1099511628211);}
static uint64_t fold_u64(uint64_t hash,uint64_t value){for(int j=0;j<8;j++){hash=fold_byte(hash,(uint8_t)value);value>>=8;}return hash;}
uint64_t epic_digest(void *context) {
    switch_ctx_t *ctx=context;uint64_t h=UINT64_C(14695981039346656037);
    for(uint32_t p=ctx->retired;p<ctx->input_count && p-ctx->retired<ctx->capacity;p++) {
        slot_state_t *slot=&ctx->slots[slot_idx(ctx,p)];
        if(!slot->in_use || slot->psn!=p)continue;
        h=fold_u64(h,p);h=fold_byte(h,slot->data_mask);h=fold_byte(h,slot->result_ready);
        if(ctx->cfg.primitive==EPIC_PRIM_ALLGATHER) {
            for(int r=0;r<4;r++) {
                h=fold_byte(h,slot->allgather_raw[r]!=NULL);
                if(slot->allgather_raw[r])for(int j=0;j<ctx->cfg.payload_bytes;j++)h=fold_byte(h,slot->allgather_raw[r][j]);
            }
        } else if(ctx->cfg.primitive==EPIC_PRIM_BCAST) {
            for(int j=0;j<ctx->cfg.payload_bytes;j++)h=fold_byte(h,slot->data.bcast_raw[j]);
        } else {
            for(int j=0;j<ctx->cfg.payload_bytes/4;j++) {
                uint32_t value;memcpy(&value,&slot->data.accum[j],4);
                for(int k=0;k<4;k++){h=fold_byte(h,(uint8_t)value);value>>=8;}
            }
        }
    }
    return h;
}
